            container "Web App" "React single-page application" "React"
            container "API" "REST API serving the web app and admin portal" "Node.js"
            container "Order Database" "Stores orders and customer data" "PostgreSQL"
            container "Admin Portal" "Internal tool for support agents" "Vue.js"

            "Customer" -> "Web App" "Places orders and browses the catalogue"
            "Web App" -> "API" "Makes requests over HTTPS"
            "API" -> "Order Database" "Reads and writes order data"
            "API" -> "Payment Gateway" "Charges cards"
            "Support Agent" -> "Admin Portal" "Manages orders"
            "Admin Portal" -> "API" "Makes requests over HTTPS"
        }
    }
    views {
        systemLandscapeView "SystemLandscape" "A landscape view of all people and systems" {
            include *
            autoLayout
        }

        systemContextView "Web Shop" "SystemContext" "Shows the Web Shop and the people and systems around it" {
            include *
            autoLayout
        }

        containerView "Web Shop" "Containers" "Shows the containers within the Web Shop" {
            include *
            autoLayout
        }
    }
}`;
