  tools.structurizr["export-plantuml"]({ dsl, viewKey: "SystemContext" }),
  tools.structurizr["export-mermaid"]({ dsl, viewKey: "SystemContext" }),
]);
const fmt = (r) => r.status === "fulfilled" ? r.value : r.reason;
return {
  parse: p1.status === "fulfilled" ? "OK" : p1.reason,
  parseConsistent: [p1, p2, p3].every(r => r.status === "fulfilled") ? "all 3 OK" : "inconsistent",
  exportPlantUML: fmt(expPlant),
  exportMermaid: fmt(expMermaid),
};

